const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');

const app = express();

// Security Middleware
app.use(helmet()); // Set security HTTP headers
app.use(express.json({ limit: '10kb' })); // Body parser with size limit
app.use(xss()); // Prevent XSS attacks
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(hpp()); // Prevent parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Health check endpoint with proper error handling
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error' 
    });
  }
});

// Users endpoint with input validation
app.get('/users', (req, res) => {
  try {
    // Validate query parameters if any
    const { limit, offset } = req.query;

    // Input validation and sanitization
    const parsedLimit = parseInt(limit) || 10;
    const parsedOffset = parseInt(offset) || 0;

    // Validate numeric parameters
    if (isNaN(parsedLimit) || isNaN(parsedOffset)) {
      return res.status(400).json({ 
        error: 'Validation failed', 
        message: 'Limit and offset must be valid numbers' 
      });
    }

    // Range validation
    if (parsedLimit < 1 || parsedLimit > 100) {
      return res.status(400).json({ 
        error: 'Validation failed', 
        message: 'Limit must be between 1 and 100' 
      });
    }

    if (parsedOffset < 0) {
      return res.status(400).json({ 
        error: 'Validation failed', 
        message: 'Offset must be a non-negative number' 
      });
    }

    // Mock data - in real app, this would come from database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' }
    ];

    // Apply pagination
    const paginatedUsers = users.slice(parsedOffset, parsedOffset + parsedLimit);

    res.json({
      count: paginatedUsers.length,
      limit: parsedLimit,
      offset: parsedOffset,
      data: paginatedUsers
    });
  } catch (error) {
    // Log the error for debugging (in production, use proper logger)
    console.error('Error in /users endpoint:', error);

    // Send generic error message to client
    res.status(500).json({ 
      error: 'Internal server error', 
      message: 'Unable to retrieve users' 
    });
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found', 
    message: `Cannot ${req.method} ${req.path}` 
  });
});

// Centralized error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Determine status code
  const statusCode = err.status || 500;

  // In production, don't leak stack traces
  const response = {
    error: err.message || 'Internal server error'
  };

  // Only include stack trace in development
  if (process.env.NODE_ENV === 'development') {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throwing an error, or other logic here
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception thrown:', error);
  // Graceful shutdown logic here
  process.exit(1);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

