// Improved Express application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');

const app = express();

// Security Middleware
app.use(helmet()); // Set security HTTP headers
app.use(express.json({ limit: '10kb' })); // Body parser with size limit
app.use(xss()); // Sanitize against XSS
app.use(mongoSanitize()); // Sanitize against NoSQL injection
app.use(hpp()); // Prevent HTTP parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.url}`);
  next();
});

// Validation middleware for query parameters
const validateQueryParams = (schema) => {
  return (req, res, next) => {
    // Simple validation example - in practice, use Joi or similar
    for (const key in schema) {
      if (req.query[key] !== undefined) {
        const value = req.query[key];
        const rules = schema[key];

        // Type validation
        if (rules.type && typeof value !== rules.type) {
          return res.status(400).json({
            error: `Validation failed`,
            message: `${key} must be of type ${rules.type}`
          });
        }

        // Pattern validation
        if (rules.pattern && !rules.pattern.test(value)) {
          return res.status(400).json({
            error: `Validation failed`,
            message: `${key} format is invalid`
          });
        }

        // Range validation for numbers
        if (rules.min !== undefined && parseFloat(value) < rules.min) {
          return res.status(400).json({
            error: `Validation failed`,
            message: `${key} must be at least ${rules.min}`
          });
        }

        if (rules.max !== undefined && parseFloat(value) > rules.max) {
          return res.status(400).json({
            error: `Validation failed`,
            message: `${key} must be at most ${rules.max}`
          });
        }
      }
    }
    next();
  };
};

// Health check endpoint with validation
app.get('/health', validateQueryParams({
  // Optional: add validation for any query params if needed
}), (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({
      error: 'Internal server error',
      message: 'Unable to process health check'
    });
  }
});

// Users endpoint with validation and error handling
app.get('/users', validateQueryParams({
  limit: {
    type: 'string',
    pattern: /^\d+$/,
    min: 1,
    max: 100
  },
  offset: {
    type: 'string',
    pattern: /^\d+$/,
    min: 0
  },
  sort: {
    type: 'string',
    pattern: /^(asc|desc)$/i
  }
}), (req, res) => {
  try {
    // Mock users data (in real app, this would come from database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' }
    ];

    // Parse and validate query parameters
    const limit = parseInt(req.query.limit) || 10;
    const offset = parseInt(req.query.offset) || 0;
    const sort = (req.query.sort || 'asc').toLowerCase();

    // Apply pagination
    const paginatedUsers = users.slice(offset, offset + limit);

    // Apply sorting
    paginatedUsers.sort((a, b) => {
      if (sort === 'asc') {
        return a.id - b.id;
      } else {
        return b.id - a.id;
      }
    });

    res.json({
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: users.length,
        hasMore: offset + limit < users.length
      }
    });
  } catch (error) {
    console.error('Error in /users endpoint:', error);
    res.status(500).json({
      error: 'Internal server error',
      message: 'Unable to retrieve users'
    });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.method} ${req.url} not found`
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Global error handler:', err);

  // Don't leak stack trace in production
  const statusCode = err.status || 500;
  const message = err.message || 'Internal server error';

  res.status(statusCode).json({
    error: statusCode === 500 ? 'Internal server error' : message,
    // Only include stack trace in development
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

