      expect(response.body).toHaveProperty('error', 'Validation failed');

      // Test valid sort values
      response = await request(app).get('/users?sort=asc');
      expect(response.status).toBe(200);

      response = await request(app).get('/users?sort=desc');
      expect(response.status).toBe(200);
    });
  });

  describe('404 Handling', () => {
    test('should return 404 for unknown routes', async () => {
      const response = await request(app).get('/unknown-route');
      expect(response.status).toBe(404);
      expect(response.body).toHaveProperty('error', 'Not found');
    });
  });

  describe('Rate Limiting', () => {
    test('should respect rate limits (basic test)', async () => {
      // Note: For a proper rate limit test, we'd need to make many requests
      // This is just a basic check that the endpoint still works
      const response = await request(app).get('/health');
      expect(response.status).toBe(200);
    });
  });
});

