const express = require('express');
const app = express();
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');

// Security middleware
app.use(helmet()); // Set security headers
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(xss()); // Sanitize against XSS
app.use(mongoSanitize()); // Sanitize against MongoDB injection
app.use(hpp()); // Protect against HTTP parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again after 15 minutes',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Request logging middleware
app.use((req, res, next) => {
  console.log(`${new Date().toISOString()} - ${req.method} ${req.originalUrl} - ${req.ip}`);
  next();
});

// Health check endpoint with validation
app.get('/health', (req, res) => {
  try {
    // Validate query parameters if any
    const detailed = req.query.detailed === 'true';

    const response = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    };

    if (detailed) {
      response.memoryUsage = process.memoryUsage();
      response.nodeVersion = process.version;
    }

    res.status(200).json(response);
  } catch (error) {
    res.status(500).json({ 
      status: 'error', 
      message: 'Internal server error during health check' 
    });
  }
});

