app.use(xss()); // Prevent XSS attacks
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(hpp()); // Prevent HTTP parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Custom request logger
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(`${req.method} ${req.originalUrl} ${res.statusCode} - ${duration}ms`);
  });
  next();
});

// Health check endpoint with validation
app.get('/health', (req, res) => {
  try {
    // Validate query parameters if any
    const { detailed } = req.query;

    if (detailed && typeof detailed !== 'string') {
      return res.status(400).json({ 
        error: 'Invalid query parameter',
        message: 'detailed parameter must be a string'
      });
    }

    const response = {
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    };

    // Only include detailed info if requested and authorized
    if (detailed === 'true' && req.headers.authorization) {
      response.memoryUsage = process.memoryUsage();
      response.nodeVersion = process.version;
    }

    res.status(200).json(response);
  } catch (error) {
    console.error('Health check error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Unable to process health check request'
    });
  }
});

// Users endpoint with proper validation and error handling
app.get('/users', (req, res) => {
  try {
    // Validate and sanitize query parameters
    const { limit, offset, search } = req.query;

    // Parse and validate numeric parameters
    const parsedLimit = limit ? parseInt(limit, 10) : 10;
    const parsedOffset = offset ? parseInt(offset, 10) : 0;

    if (isNaN(parsedLimit) || isNaN(parsedOffset)) {
      return res.status(400).json({ 
        error: 'Validation failed',
        message: 'limit and offset must be valid numbers'
      });
    }

    // Validate range
    if (parsedLimit < 1 || parsedLimit > 100) {
      return res.status(400).json({ 
        error: 'Validation failed',
        message: 'limit must be between 1 and 100'
      });
    }

    if (parsedOffset < 0) {
      return res.status(400).json({ 
        error: 'Validation failed',
        message: 'offset must be a non-negative number'
      });
    }

    // Validate search parameter (if provided)
    let filteredUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' }
    ];

    if (search) {
      if (typeof search !== 'string' || search.length > 50) {
        return res.status(400).json({ 
          error: 'Validation failed',
          message: 'search must be a string with maximum length of 50 characters'
        });
      }

      // Simple case-insensitive search
      const searchTerm = search.toLowerCase().trim();
      filteredUsers = filteredUsers.filter(user => 
        user.name.toLowerCase().includes(searchTerm) || 
        user.email.toLowerCase().includes(searchTerm)
      );
    }

    // Apply pagination
    const paginatedUsers = filteredUsers.slice(parsedOffset, parsedOffset + parsedLimit);

    res.status(200).json({
      count: filteredUsers.length,
      limit: parsedLimit,
      offset: parsedOffset,
      data: paginatedUsers
    });
  } catch (error) {
    console.error('Users endpoint error:', error);
    res.status(500).json({ 
      error: 'Internal server error',
      message: 'Unable to process users request'
    });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Route ${req.originalUrl} not found`
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Global error handler:', err);

  // Set default status code
  const statusCode = err.status || 500;

  res.status(statusCode).json({
    error: statusCode === 500 ? 'Internal server error' : 'Bad request',
    message: process.env.NODE_ENV === 'production' 
      ? 'Something went wrong' 
      : err.message || 'An unknown error occurred'
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

