// Improved application with error handling, input validation, and security best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, validationResult, param, query } = require('express-validator');
const xss = require('xss');
const app = express();

// Security middleware
app.use(helmet());

// Rate limiting to prevent abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Body parsing middleware
app.use(express.json({ limit: '10kb' })); // Limit JSON payload size
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Health check endpoint with validation
app.get('/health', 
  [
    // Validate query parameters if any are expected
    query('detailed').optional().isBoolean().toBoolean()
  ],
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const response = {
      status: 'ok',
      timestamp: new Date().toISOString()
    };

    // Add detailed info if requested and validated
    if (req.query.detailed) {
      response.uptime = process.uptime();
      response.memoryUsage = process.memoryUsage();
    }

    res.json(response);
  }
);

// Users endpoint with validation and sanitization
app.get('/users', 
  [
    // Validate and sanitize query parameters
    query('limit')
      .optional()
      .isInt({ gt: 0 })
      .withMessage('Limit must be a positive integer')
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer')
      .toInt(),
    query('search')
      .optional()
      .isString()
      .trim()
      .escape()
  ],
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Sample data - in a real app, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' }
    ];

    // Apply search filter if provided
    let filteredUsers = users;
    if (req.query.search) {
      const searchTerm = req.query.search.toLowerCase();
      filteredUsers = users.filter(user => 
        user.name.toLowerCase().includes(searchTerm) || 
        user.email.toLowerCase().includes(searchTerm)
      );
    }

    // Apply pagination
    const limit = req.query.limit || filteredUsers.length;
    const offset = req.query.offset || 0;
    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    // Sanitize output to prevent XSS
    const sanitizedUsers = paginatedUsers.map(user => ({
      id: user.id,
      name: xss(user.name),
      email: xss(user.email)
    }));

    res.json({
      count: sanitizedUsers.length,
      limit,
      offset,
      users: sanitizedUsers
    });
  }
);

// Individual user endpoint with parameter validation
app.get('/users/:id', 
  [
    // Validate route parameter
    param('id')
      .isInt({ gt: 0 })
      .withMessage('User ID must be a positive integer')
  ],
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const userId = parseInt(req.params.id);

    // Sample data - in a real app, this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' }
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    // Sanitize output
    res.json({
      id: user.id,
      name: xss(user.name),
      email: xss(user.email)
    });
  }
);

// POST endpoint example with validation
app.post('/users', 
  [
    // Validate and sanitize request body
    body('name')
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .escape(),
    body('email')
      .trim()
      .isEmail()
      .withMessage('Please provide a valid email address')
      .normalizeEmail()
  ],
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // In a real app, save to database
    const newUser = {
      id: Date.now(), // Simple ID generation for demo
      name: xss(req.body.name),
      email: xss(req.body.email)
    };

    res.status(201).json(newUser);
  }
);

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Cannot ${req.method} ${req.path}`
  });
});

// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Global error handler:', err);

  // Determine status code
  const statusCode = err.status || 500;

  // Don't leak stack trace in production
  const response = {
    error: statusCode === 500 ? 'Internal Server Error' : err.message,
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  };

  res.status(statusCode).json(response);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // Application specific logging, throwing an error, or other logic here
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception thrown:', err);
  // Perform cleanup operations before exiting
  process.exit(1);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Process terminated');
  });
});

module.exports = app;

