// Improved application with proper error handling, input validation, and security practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const mongoSanitize = require('express-mongo-sanitize');
const hpp = require('hpp');
const cors = require('cors');
const { validateUserQuery } = require('./middleware/validation'); // Custom validation middleware

const app = express();

// Security middleware
app.use(helmet({                    // Set security HTTP headers
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
    }
  }
}));
app.use(cors());                    // Enable CORS
app.use(express.json({ limit: '10kb' })); // Body parser with size limit
app.use(xss());                     // Sanitize against XSS
app.use(mongoSanitize());           // Sanitize against NoSQL injection
app.use(hpp());                     // Prevent HTTP parameter pollution

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                 // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again after 15 minutes'
  },
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Routes with proper error handling
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    res.status(500).json({
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'development' ? error.message : undefined
    });
  }
});

app.get('/users', validateUserQuery, (req, res) => {
  try {
    // Simulate database query with sanitized inputs
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply filters based on validated query parameters
    const filteredUsers = users.filter(user => {
      if (req.query.name && !user.name.toLowerCase().includes(req.query.name.toLowerCase())) {
        return false;
      }
      if (req.query.email && !user.email.toLowerCase().includes(req.query.email.toLowerCase())) {
        return false;
      }
      return true;
    });

    res.json({
      status: 'success',
      count: filteredUsers.length,
      data: filteredUsers
    });
  } catch (error) {
    // Log error for monitoring (in production, use proper logging library)
    console.error('Error fetching users:', error);

    res.status(500).json({
      error: 'Internal server error',
      message: process.env.NODE_ENV === 'development' ? error.message : undefined
    });
  }
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `Cannot ${req.method} ${req.originalUrl}`
  });
});

// Centralized error handling middleware
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err); // Log error

  // Default error status
  const statusCode = err.statusCode || 500;

  res.status(statusCode).json({
    error: statusCode === 500 ? 'Internal server error' : err.message,
    // Only show detailed error in development
    ...(process.env.NODE_ENV === 'development' && { 
      stack: err.stack,
      details: err.details 
    })
  });
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (err) => {
  console.error('UNHANDLED REJECTION! 💥 Shutting down...');
  console.error(err.name, err.message);
  server.close(() => {
    process.exit(1);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION! 💥 Shutting down...');
  console.error(err.name, err.message);
  process.exit(1);
});

module.exports = app;

// Validation middleware for input sanitization and validation
const { validate } = require('express-validation');
const Joi = require('joi');

// Validation schema for user queries
const userQuerySchema = {
  query: Joi.object({
    name: Joi.string()
      .trim()
      .max(50)
      .pattern(/^[a-zA-Z\s\-']*$/) // Allow only letters, spaces, hyphens, and apostrophes
      .optional(),
    email: Joi.string()
      .trim()
      .max(100)
      .email({ tlds: { allow: false } }) // Basic email validation
      .optional(),
    limit: Joi.number()
      .integer()
      .min(1)
      .max(100)
      .default(10),
    offset: Joi.number()
      .integer()
      .min(0)
      .default(0)
  })
};

// Middleware function to validate user queries
function validateUserQuery(req, res, next) {
  const { error, value } = userQuerySchema.query.validate(req.query, {
    abortEarly: false, // Collect all errors
    stripUnknown: true // Remove unknown properties
  });

  if (error) {
    // Format Joi error details
    const details = error.details.map(detail => ({
      field: detail.path.join('.'),
      message: detail.message
    }));

    return res.status(400).json({
      error: 'Validation failed',
      details: details
    });
  }

  // Replace validated query params
  req.query = value;
  next();
}

module.exports = { validateUserQuery };

// Test file for app.js validation and error handling
const request = require('supertest');
const app = require('./app');

describe('API Endpoints', () => {
  afterAll(() => {
    // Close the server after tests
    app.close();
  });

  describe('GET /health', () => {
    it('should return 200 OK', async () => {
      const res = await request(app).get('/health');
      expect(res.statusCode).toEqual(200);
      expect(res.body).toHaveProperty('status', 'ok');
      expect(res.body).toHaveProperty('timestamp');
    });
  });

  describe('GET /users', () => {
    it('should return users list', async () => {
      const res = await request(app).get('/users');
      expect(res.statusCode).toEqual(200);
      expect(res.body).toHaveProperty('status', 'success');
      expect(res.body.data).toBeInstanceOf(Array);
      expect(res.body.data.length).toBeGreaterThan(0);
    });

    it('should validate query parameters', async () => {
      const res = await request(app)
        .get('/users')
        .query({ name: 'ValidName', email: 'test@example.com' });

      expect(res.statusCode).toEqual(200);
    });

    it('should reject invalid name in query', async () => {
      const res = await request(app)
        .get('/users')
        .query({ name: 'InvalidName123!' }); // Contains numbers and special chars

      expect(res.statusCode).toEqual(400);
      expect(res.body).toHaveProperty('error', 'Validation failed');
    });

    it('should reject invalid email in query', async () => {
      const res = await request(app)
        .get('/users')
        .query({ email: 'not-an-email' });

      expect(res.statusCode).toEqual(400);
      expect(res.body).toHaveProperty('error', 'Validation failed');
    });

    it('should sanitize inputs against XSS', async () => {
      const res = await request(app)
        .get('/users')
        .query({ name: '<script>alert(1)</script>' });

      // Should either reject or sanitize the input
      // Depending on implementation, this might be 400 or 200 with sanitized data
      expect(res.statusCode).toBeOneOf([200, 400]);
    });

    it('should handle rate limiting', async () => {
      // Make multiple requests quickly to trigger rate limit
      const promises = [];
      for (let i = 0; i > 105; i++) {
        promises.push(request(app).get('/health'));
      }

      const responses = await Promise.all(promises);
      const statusCodes = responses.map(r => r.statusCode);

      // Should have at least one rate-limited response
      expect(statusCodes.some(code => code === 429)).toBe(true);
    });
  });
});

